// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QStampVault v2 - $1 USDG stamps for QMessenger cold hellos (no token)
/// @notice Chat inside an accepted conversation is free and off-chain. Only the first cold hello to someone who has
///         not accepted you carries a stamp: a fixed USDG escrow (`stampPrice`, $1).
///         - Accept before expiry: the recipient gets stampPrice - cut; the cut accrues for the QHOOKS buyback sink.
///         - Decline (recipient) or expiry (anyone may call refund): the full stamp goes back to its `refundTo`.
///         - Credit stamps: free stamps from cumulative Merkle roots (welcome + monthly holder credits). Credits are
///           counters, never tokens: no transfer, no withdraw. A credit stamp can only go to a verified recipient
///           (registered inbox key, older than `inboxMinAge`), once per (sender, recipient) pair, within per-season
///           caps. On accept the recipient is paid `creditPayout` from a treasury-funded credit pool, if the pool
///           backed the stamp when it was sent (otherwise the hello is delivered with no payout).
///         - Sponsors (card/bank onramp, relayer, zap) pay on behalf of a sender with `stampFor`; the refund address
///           is fixed by the payer at send time and nobody can change it afterwards.
/// @dev    Single currency (USDG), fixed price, no oracle, no pause, no upgrade. Roles: `admin` (immutable, the Safe)
///         may rotate the credit issuer, withdraw the unreserved credit pool and rescue excess balances; the
///         `creditIssuer` may post credit roots. Neither can touch escrowed stamps, owed payouts or the pending cut.
///         Outgoing pushes that fail (frozen holder, paused token, frozen sink) are credited to `owed` for that same
///         address and pulled later (withdraw / withdrawFor). The vault never routes USDG around an issuer freeze:
///         acceptTo / withdrawTo refuse frozen accounts (independent audit M-1, fixed 2026-11-16).
contract QStampVault {
    // ------------------------------------------------------------------ constants

    uint256 internal constant BPS = 10_000;
    /// @notice Hard ceiling on the cut: 2000 bps = 20%.
    uint256 public constant MAX_CUT_BPS = 2000;
    /// @notice Length of a credit season (caps reset each season). Season 0 starts at deployment.
    uint64 public constant SEASON = 30 days;
    uint64 public constant MIN_EXPIRY = 1 hours;
    uint64 public constant MAX_EXPIRY = 30 days;
    uint64 public constant MAX_INBOX_MIN_AGE = 30 days;
    /// @notice Sanity ceiling on a lifetime credit leaf (stamps, not token wei).
    uint256 public constant MAX_CREDITS = 10_000;

    bytes32 internal constant REGISTER_TYPEHASH =
        keccak256("RegisterInbox(address wallet,bytes32 keyHash,uint256 nonce,uint256 deadline)");
    bytes32 internal constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes4 internal constant ERC1271_MAGIC = 0x1626ba7e;
    uint256 internal constant HALF_N = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    // ------------------------------------------------------------------ immutables

    /// @notice The Safe. Rotates the credit issuer, withdraws the unreserved credit pool, rescues excess.
    address public immutable admin;
    /// @notice The only stamp currency (USDG on Robinhood Chain, 6 decimals).
    address public immutable usdg;
    /// @notice Receives the accrued cut (QHOOKS buyback destination). Fixed forever.
    address public immutable buybackSink;
    /// @notice Price of one stamp in USDG units (1e6 = $1).
    uint256 public immutable stampPrice;
    /// @notice Cut on accepted paid stamps, bps, <= MAX_CUT_BPS, rounded up.
    uint256 public immutable cutBps;
    /// @notice Stamp lifetime. Accept/decline while now < expiresAt; refund from expiresAt on.
    uint64 public immutable expiry;
    /// @notice USDG paid to the recipient of an accepted, pool-backed credit stamp (<= stampPrice; 0 = never paid).
    uint256 public immutable creditPayout;
    /// @notice A registered inbox counts as verified only this long after its first registration.
    uint64 public immutable inboxMinAge;
    /// @notice Max credit stamps one sender may send per season (every send counts; refunds don't give it back).
    uint32 public immutable senderSeasonCap;
    /// @notice Max credit stamps sent across all senders per season (every send counts).
    uint32 public immutable globalSeasonCap;
    /// @notice Max paid credit accepts per recipient per season (counted at accept, in the accept's season).
    uint32 public immutable recipientSeasonCap;
    /// @notice Max USDG of credit-pool backing committed per season (live + paid; refunds free it).
    uint256 public immutable seasonBackingCap;
    /// @notice Start of season 0.
    uint64 public immutable genesis;
    bytes32 internal immutable _domainSeparator;
    uint256 internal immutable _chainId;

    // ------------------------------------------------------------------ roles

    address public creditIssuer;

    // ------------------------------------------------------------------ stamps

    enum Status {
        None,
        Live,
        Accepted,
        Refunded
    }

    struct Stamp {
        address refundTo; // paid stamps: who gets the refund (fixed by the payer); credit stamps: address(0)
        uint64 expiresAt;
        uint16 season;
        Status status;
        bool credit;
        address sender;
        uint96 amount; // paid: stampPrice; credit: creditPayout if pool-backed, else 0
        address recipient;
    }

    /// key = stampKey(sender, helloId, payer): self-paid and credit stamps live in the sender's own namespace;
    /// sponsored stamps (payer != sender) live in a (sender, payer) namespace, so nobody can squat a sender's ids.
    mapping(bytes32 => Stamp) internal _stamps;

    // ------------------------------------------------------------------ USDG buckets (balance == sum of these)

    /// @notice Escrow of live paid stamps.
    uint256 public livePaid;
    /// @notice Pool money committed to live credit stamps.
    uint256 public liveBacking;
    /// @notice Unreserved credit pool (treasury-funded; backs credit stamps at send time).
    uint256 public creditPool;
    /// @notice Cut not yet flushed to the buyback sink.
    uint256 public pendingCut;
    /// @notice Failed pushes waiting to be pulled.
    mapping(address => uint256) public owed;
    uint256 public totalOwed;

    // ------------------------------------------------------------------ credits

    bytes32 public creditRoot;
    uint64 public creditRound;
    /// @notice Highest cumulative credit amount proven for an account (stamps, not USDG).
    mapping(address => uint256) public creditsKnown;
    /// @notice Credits tied up in live or accepted credit stamps. available = known - used.
    mapping(address => uint256) public creditsUsed;
    /// @notice Credit stamps sent per sender per season. Only ever goes up: refunds (decline or expiry) return the
    ///         credit but never the season slot, so a slot cannot be recycled for free (audit L-4).
    mapping(address => mapping(uint256 => uint256)) public seasonSent;
    mapping(uint256 => uint256) public seasonSentGlobal; // season => count, only goes up
    /// @notice Paid credit accepts per recipient per season, counted at accept time (only the recipient fills it).
    mapping(address => mapping(uint256 => uint256)) public seasonPaidTo;
    mapping(uint256 => uint256) public seasonBacking; // season => USDG committed (live + paid), freed on refund

    enum Pair {
        None,
        Live,
        Accepted,
        Declined
    }

    /// @notice Credit stamp state per (sender, recipient): at most one live, never again once accepted, and none
    ///         for the rest of the season once declined (audit R-4). An expired (ignored) stamp frees the pair.
    mapping(address => mapping(address => Pair)) public creditPair;
    /// @notice Season in which a pair was declined, plus 1 (0 = never declined).
    mapping(address => mapping(address => uint256)) public pairDeclinedSeason;

    // ------------------------------------------------------------------ inbox registry

    struct Inbox {
        bytes32 keyHash; // keccak256 of the QMessenger inbox public key
        uint64 registeredAt; // first registration; rotation keeps it
    }

    mapping(address => Inbox) public inboxes;
    mapping(address => uint256) public inboxNonce;

    uint256 internal _lock = 1;

    // ------------------------------------------------------------------ events

    event StampSent(
        bytes32 indexed key,
        address indexed sender,
        address indexed recipient,
        bytes32 helloId,
        address payer,
        address refundTo,
        uint256 amount,
        bool credit,
        uint64 expiresAt
    );
    event StampAccepted(bytes32 indexed key, address indexed recipient, address payTo, uint256 payout, uint256 cut);
    event StampRefunded(bytes32 indexed key, address indexed refundTo, uint256 amount, bool credit, bool declined);
    event InboxRegistered(address indexed wallet, bytes32 keyHash, uint64 registeredAt);
    event InboxNonceCancelled(address indexed wallet, uint256 newNonce);
    event CreditRootSet(uint64 indexed round, bytes32 root, address indexed by);
    event CreditIssuerSet(address indexed issuer);
    event CreditsProven(address indexed account, uint256 cumulative);
    event CreditPoolFunded(address indexed from, uint256 amount);
    event CreditPoolWithdrawn(address indexed to, uint256 amount);
    event CutFlushed(address indexed sink, uint256 amount);
    event PayoutDeferred(address indexed to, uint256 amount);
    event Withdrawn(address indexed account, address to, uint256 amount);
    event Rescued(address indexed token, address indexed to, uint256 amount);

    // ------------------------------------------------------------------ errors

    error NotAdmin();
    error NotIssuer();
    error BadParams();
    error BadAddress();
    error HelloIdUsed();
    error NotLive();
    error NotRecipient();
    error Expired();
    error NotExpired();
    error TransferFailed();
    error AmountMismatch(uint256 expected, uint256 received);
    error Reentrancy();
    error BadProof();
    error NoCredits();
    error RecipientNotVerified();
    error PairUsed();
    error SenderSeasonCap();
    error GlobalSeasonCap();
    error NothingToWithdraw();
    error BadSignature();
    error SignatureExpired();
    error Frozen(address account);
    error FreezeCheckFailed();

    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    struct Config {
        address admin; // the Safe
        address usdg; // USDG (must have code)
        address buybackSink; // QHOOKS buyback destination (fixed)
        address creditIssuer; // posts credit roots (zero = none until admin sets one)
        uint256 stampPrice; // 1e6 = $1
        uint256 cutBps; // <= 2000
        uint64 expiry; // 1h..30d
        uint256 creditPayout; // <= stampPrice
        uint64 inboxMinAge; // <= 30d
        uint32 senderSeasonCap;
        uint32 globalSeasonCap;
        uint32 recipientSeasonCap;
        uint256 seasonBackingCap;
    }

    constructor(Config memory c) {
        if (c.admin == address(0) || c.buybackSink == address(0) || c.buybackSink == address(this)) {
            revert BadAddress();
        }
        if (c.usdg.code.length == 0) revert BadAddress();
        if (c.stampPrice == 0 || c.stampPrice > type(uint96).max) revert BadParams();
        if (c.cutBps > MAX_CUT_BPS || c.creditPayout > c.stampPrice) revert BadParams();
        if (c.expiry < MIN_EXPIRY || c.expiry > MAX_EXPIRY || c.inboxMinAge > MAX_INBOX_MIN_AGE) revert BadParams();
        if (c.senderSeasonCap == 0 || c.globalSeasonCap < c.senderSeasonCap) revert BadParams();
        if (c.creditPayout != 0 && (c.recipientSeasonCap == 0 || c.seasonBackingCap < c.creditPayout)) {
            revert BadParams();
        }
        admin = c.admin;
        usdg = c.usdg;
        buybackSink = c.buybackSink;
        stampPrice = c.stampPrice;
        cutBps = c.cutBps;
        expiry = c.expiry;
        creditPayout = c.creditPayout;
        inboxMinAge = c.inboxMinAge;
        senderSeasonCap = c.senderSeasonCap;
        globalSeasonCap = c.globalSeasonCap;
        recipientSeasonCap = c.recipientSeasonCap;
        seasonBackingCap = c.seasonBackingCap;
        genesis = uint64(block.timestamp);
        _chainId = block.chainid;
        _domainSeparator = _buildDomain();
        creditIssuer = c.creditIssuer;
        emit CreditIssuerSet(c.creditIssuer);
    }

    // ================================================================== paid stamps

    /// @notice Sender pays its own stamp (approve USDG first). Refund goes back to the sender.
    function sendStamp(address recipient, bytes32 helloId) external nonReentrant returns (bytes32 key) {
        key = _paidStamp(msg.sender, recipient, helloId, msg.sender);
    }

    /// @notice Same as sendStamp with an EIP-2612 permit in the same tx (USDG supports permit). A permit that was
    ///         already used (front-run) is ignored; the pull still needs enough allowance.
    function sendStampWithPermit(address recipient, bytes32 helloId, uint256 deadline, uint8 v, bytes32 r, bytes32 s)
        external
        nonReentrant
        returns (bytes32 key)
    {
        _tryPermit(msg.sender, deadline, v, r, s);
        key = _paidStamp(msg.sender, recipient, helloId, msg.sender);
    }

    /// @notice Sponsor / onramp / relayer path: msg.sender pays a stamp on behalf of `sender`. The payer fixes
    ///         `refundTo` now (itself, or the end user); it cannot be changed later by anyone. Accept always pays the
    ///         recipient. `sender` is attribution only: QMessenger shows the hello only if it is signed by
    ///         `sender`'s inbox key, so paying for someone else gives the payer nothing. When payer != sender the
    ///         stamp lives in the (sender, payer) key namespace and can never block the sender's own sends.
    function stampFor(address sender, address recipient, bytes32 helloId, address refundTo)
        external
        nonReentrant
        returns (bytes32 key)
    {
        if (sender == address(0) || refundTo == address(0) || refundTo == address(this)) revert BadAddress();
        key = _paidStamp(sender, recipient, helloId, refundTo);
    }

    function _paidStamp(address sender, address recipient, bytes32 helloId, address refundTo)
        internal
        returns (bytes32 key)
    {
        key = _newKey(sender, recipient, helloId, msg.sender);
        uint64 expiresAt = uint64(block.timestamp) + expiry;
        uint256 amount = stampPrice;
        _stamps[key] = Stamp({
            refundTo: refundTo,
            expiresAt: expiresAt,
            season: uint16(currentSeason()),
            status: Status.Live,
            credit: false,
            sender: sender,
            amount: uint96(amount),
            recipient: recipient
        });
        livePaid += amount;
        emit StampSent(key, sender, recipient, helloId, msg.sender, refundTo, amount, false, expiresAt);
        _pullExact(msg.sender, amount);
    }

    // ================================================================== credit stamps

    /// @notice Spend one credit on a stamp to a verified recipient. Pass the account's cumulative credit leaf and
    ///         proof when it is higher than `creditsKnown` (first use, or after a new monthly root); otherwise pass 0
    ///         and an empty proof.
    function sendCreditStamp(address recipient, bytes32 helloId, uint256 cumulative, bytes32[] calldata proof)
        external
        nonReentrant
        returns (bytes32 key)
    {
        address sender = msg.sender;
        if (cumulative > creditsKnown[sender]) {
            if (cumulative > MAX_CREDITS) revert BadParams();
            if (!verify(proof, creditRoot, creditLeaf(sender, cumulative))) revert BadProof();
            creditsKnown[sender] = cumulative;
            emit CreditsProven(sender, cumulative);
        }
        if (creditsUsed[sender] >= creditsKnown[sender]) revert NoCredits();
        if (!isVerified(recipient)) revert RecipientNotVerified();
        uint256 season = currentSeason();
        Pair pair = creditPair[sender][recipient];
        if (pair == Pair.Live || pair == Pair.Accepted) revert PairUsed();
        if (pair == Pair.Declined && pairDeclinedSeason[sender][recipient] == season + 1) revert PairUsed();
        if (seasonSent[sender][season] >= senderSeasonCap) revert SenderSeasonCap();
        if (seasonSentGlobal[season] >= globalSeasonCap) revert GlobalSeasonCap();

        key = _newKey(sender, recipient, helloId, sender); // also rejects self / zero / this recipients

        uint256 backing = creditPayout;
        if (
            backing == 0 || creditPool < backing || seasonPaidTo[recipient][season] >= recipientSeasonCap
                || seasonBacking[season] + backing > seasonBackingCap
        ) {
            backing = 0; // hello still delivered; recipient is told up front there is no payout
        } else {
            creditPool -= backing;
            liveBacking += backing;
            seasonBacking[season] += backing;
        }

        creditsUsed[sender] += 1;
        seasonSent[sender][season] += 1;
        seasonSentGlobal[season] += 1;
        creditPair[sender][recipient] = Pair.Live;

        uint64 expiresAt = uint64(block.timestamp) + expiry;
        _stamps[key] = Stamp({
            refundTo: address(0),
            expiresAt: expiresAt,
            season: uint16(season),
            status: Status.Live,
            credit: true,
            sender: sender,
            amount: uint96(backing),
            recipient: recipient
        });
        emit StampSent(key, sender, recipient, helloId, address(0), address(0), backing, true, expiresAt);
    }

    // ================================================================== settle

    /// @notice Recipient accepts before expiry. Paid stamp: stampPrice - cut. Credit stamp: its pool backing, no cut,
    ///         if the recipient is still under recipientSeasonCap paid credit accepts this season (else the backing
    ///         goes back to the pool and the payout is 0).
    function accept(bytes32 key) external nonReentrant {
        _accept(key, msg.sender);
    }

    /// @notice Same as accept, paying `payTo` (e.g. a contract recipient's treasury). Refused if the recipient or
    ///         `payTo` is frozen in USDG: the vault never routes money around an issuer freeze (audit M-1).
    function acceptTo(bytes32 key, address payTo) external nonReentrant {
        if (payTo == address(0) || payTo == address(this)) revert BadAddress();
        _notFrozen(msg.sender);
        _notFrozen(payTo);
        _accept(key, payTo);
    }

    function _accept(bytes32 key, address payTo) internal {
        Stamp storage s = _stamps[key];
        if (s.status != Status.Live) revert NotLive();
        if (msg.sender != s.recipient) revert NotRecipient();
        if (block.timestamp >= s.expiresAt) revert Expired();
        s.status = Status.Accepted;
        uint256 amount = s.amount;
        uint256 cut;
        if (s.credit) {
            creditPair[s.sender][s.recipient] = Pair.Accepted; // credits stay used; season counters stay
            if (amount != 0) {
                liveBacking -= amount;
                uint256 season = currentSeason();
                if (seasonPaidTo[s.recipient][season] < recipientSeasonCap) {
                    seasonPaidTo[s.recipient][season] += 1;
                } else {
                    creditPool += amount; // recipient already took its paid accepts this season
                    seasonBacking[s.season] -= amount;
                    amount = 0;
                }
            }
        } else {
            livePaid -= amount;
            cut = cutOf(amount);
            pendingCut += cut;
        }
        uint256 payout = amount - cut;
        emit StampAccepted(key, msg.sender, payTo, payout, cut);
        _pay(payTo, payout);
    }

    /// @notice Recipient turns the stamp down before expiry; refunded at once.
    function decline(bytes32 key) external nonReentrant {
        Stamp storage s = _stamps[key];
        if (s.status != Status.Live) revert NotLive();
        if (msg.sender != s.recipient) revert NotRecipient();
        if (block.timestamp >= s.expiresAt) revert Expired();
        _refund(key, s, true);
    }

    /// @notice From expiry on, anyone may refund. Paid stamps go to the stored refundTo; credit stamps give the
    ///         credit back to the sender and the backing back to the pool (the season slot stays used).
    ///         Kept permissionless so expired escrow can always be closed; a push that fails (pause/freeze) parks
    ///         the money in owed[refundTo], which anyone can later deliver to that same address with withdrawFor.
    function refund(bytes32 key) external nonReentrant {
        Stamp storage s = _stamps[key];
        if (s.status != Status.Live) revert NotLive();
        if (block.timestamp < s.expiresAt) revert NotExpired();
        _refund(key, s, false);
    }

    function _refund(bytes32 key, Stamp storage s, bool declined) internal {
        s.status = Status.Refunded;
        uint256 amount = s.amount;
        if (s.credit) {
            address sender = s.sender;
            creditsUsed[sender] -= 1; // credit back; season slots (seasonSent / global) stay consumed
            if (declined) {
                creditPair[sender][s.recipient] = Pair.Declined; // closed until next season (R-4)
                pairDeclinedSeason[sender][s.recipient] = currentSeason() + 1;
            } else {
                creditPair[sender][s.recipient] = Pair.None;
            }
            if (amount != 0) {
                liveBacking -= amount;
                creditPool += amount;
                seasonBacking[s.season] -= amount;
            }
            emit StampRefunded(key, sender, amount, true, declined);
        } else {
            livePaid -= amount;
            address to = s.refundTo;
            emit StampRefunded(key, to, amount, false, declined);
            _pay(to, amount);
        }
    }

    // ================================================================== cut, pool, owed

    /// @notice Anyone may push the accrued cut to the fixed buyback sink. If the push fails (sink frozen, USDG
    ///         paused) the cut is parked in owed[buybackSink] instead of being stuck (audit L-1).
    function flushCut() external nonReentrant {
        uint256 cut = pendingCut;
        if (cut == 0) revert NothingToWithdraw();
        pendingCut = 0;
        emit CutFlushed(buybackSink, cut);
        _pay(buybackSink, cut);
    }

    /// @notice Anyone (normally the Safe) adds USDG to the credit pool.
    function fundCreditPool(uint256 amount) external nonReentrant {
        if (amount == 0) revert BadParams();
        creditPool += amount;
        emit CreditPoolFunded(msg.sender, amount);
        _pullExact(msg.sender, amount);
    }

    /// @notice Admin takes back unreserved pool money (never backing already committed to live stamps).
    function withdrawCreditPool(uint256 amount) external onlyAdmin nonReentrant {
        if (amount == 0 || amount > creditPool) revert BadParams();
        creditPool -= amount;
        emit CreditPoolWithdrawn(admin, amount);
        if (!_tryTransfer(usdg, admin, amount)) revert TransferFailed();
    }

    function withdraw() external nonReentrant {
        _withdraw(msg.sender, msg.sender);
    }

    /// @notice Pull owed to another address. Refused while the caller is frozen in USDG (audit M-1).
    function withdrawTo(address to) external nonReentrant {
        if (to == address(0) || to == address(this)) revert BadAddress();
        _notFrozen(msg.sender);
        _withdraw(msg.sender, to);
    }

    /// @notice Anyone may deliver an account's owed balance to that same account (never elsewhere). Lets sponsor
    ///         contracts without a withdraw call, and the cut sink, receive parked money once USDG unpauses (L-5).
    function withdrawFor(address account) external nonReentrant {
        _withdraw(account, account);
    }

    function _withdraw(address account, address to) internal {
        uint256 amt = owed[account];
        if (amt == 0) revert NothingToWithdraw();
        owed[account] = 0;
        totalOwed -= amt;
        emit Withdrawn(account, to, amt);
        if (!_tryTransfer(usdg, to, amt)) revert TransferFailed();
    }

    // ================================================================== roles

    function setCreditIssuer(address issuer) external onlyAdmin {
        creditIssuer = issuer;
        emit CreditIssuerSet(issuer);
    }

    /// @notice Posts the cumulative credit root (leaf = account, lifetime credits). Proven amounts never go down.
    function setCreditRoot(bytes32 root) external {
        if (msg.sender != creditIssuer || msg.sender == address(0)) revert NotIssuer();
        if (root == bytes32(0)) revert BadParams();
        creditRoot = root;
        uint64 round = ++creditRound;
        emit CreditRootSet(round, root, msg.sender);
    }

    /// @notice Sends tokens sent here by mistake to the admin. For USDG only the balance above `reserved()`.
    ///         `token == address(0)` rescues ETH (only reachable via selfdestruct / coinbase; no function is payable).
    function rescue(address token) external onlyAdmin nonReentrant {
        uint256 amt;
        if (token == address(0)) {
            amt = address(this).balance;
            if (amt == 0) revert NothingToWithdraw();
            emit Rescued(token, admin, amt);
            (bool ok,) = admin.call{value: amt}("");
            if (!ok) revert TransferFailed();
            return;
        }
        uint256 bal = _balanceOf(token, address(this));
        uint256 r = token == usdg ? reserved() : 0;
        if (bal <= r) revert NothingToWithdraw();
        amt = bal - r;
        emit Rescued(token, admin, amt);
        if (!_tryTransfer(token, admin, amt)) revert TransferFailed();
    }

    // ================================================================== inbox registry

    /// @notice The wallet registers (or rotates) its QMessenger inbox key hash. First registration starts the
    ///         verification clock; rotation keeps it.
    ///         It also bumps the wallet's signature nonce, so an unsubmitted RegisterInbox signature can never roll a
    ///         direct rotation back (audit L-2).
    function registerInbox(bytes32 keyHash) external {
        inboxNonce[msg.sender]++;
        _register(msg.sender, keyHash);
    }

    /// @notice Invalidates every outstanding RegisterInbox signature of the caller.
    function cancelInboxNonce() external {
        uint256 n = ++inboxNonce[msg.sender];
        emit InboxNonceCancelled(msg.sender, n);
    }

    /// @notice Gasless registration: anyone relays the wallet's EIP-712 RegisterInbox signature (EOA or ERC-1271).
    function registerInboxBySig(address wallet, bytes32 keyHash, uint256 deadline, bytes calldata sig) external {
        if (block.timestamp > deadline) revert SignatureExpired();
        uint256 nonce = inboxNonce[wallet]++;
        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01", domainSeparator(), keccak256(abi.encode(REGISTER_TYPEHASH, wallet, keyHash, nonce, deadline))
            )
        );
        if (!_validSig(wallet, digest, sig)) revert BadSignature();
        _register(wallet, keyHash);
    }

    function _register(address wallet, bytes32 keyHash) internal {
        if (keyHash == bytes32(0) || wallet == address(0)) revert BadParams();
        Inbox storage ib = inboxes[wallet];
        ib.keyHash = keyHash;
        if (ib.registeredAt == 0) ib.registeredAt = uint64(block.timestamp);
        emit InboxRegistered(wallet, keyHash, ib.registeredAt);
    }

    // ================================================================== views

    function getStamp(bytes32 key) external view returns (Stamp memory) {
        return _stamps[key];
    }

    /// @notice Key of a stamp. Self-paid and credit stamps: payer == sender. Sponsored: payer = the stampFor caller.
    function stampKey(address sender, bytes32 helloId, address payer) public pure returns (bytes32) {
        return payer == sender
            ? keccak256(abi.encode(sender, helloId))
            : keccak256(abi.encode(sender, helloId, payer));
    }

    /// @notice True if USDG reports `account` frozen. Fails CLOSED (reverts FreezeCheckFailed) if isFrozen reverts,
    ///         is missing, or returns anything but a 32-byte 0/1 (audit R-1). Only acceptTo / withdrawTo depend on
    ///         it; accept, decline, refund, withdraw, withdrawFor and flushCut never call it, so they can't brick.
    function isFrozen(address account) public view returns (bool) {
        (bool ok, bytes memory ret) = usdg.staticcall(abi.encodeWithSelector(0xe5839836, account));
        if (!ok || ret.length != 32) revert FreezeCheckFailed();
        uint256 word = abi.decode(ret, (uint256));
        if (word > 1) revert FreezeCheckFailed();
        return word == 1;
    }

    function currentSeason() public view returns (uint256) {
        return (block.timestamp - genesis) / SEASON;
    }

    /// @notice Recipient counts as verified for credit stamps.
    function isVerified(address wallet) public view returns (bool) {
        uint64 at = inboxes[wallet].registeredAt;
        return at != 0 && block.timestamp >= uint256(at) + inboxMinAge;
    }

    function creditsAvailable(address account) external view returns (uint256) {
        uint256 k = creditsKnown[account];
        uint256 u = creditsUsed[account];
        return k > u ? k - u : 0;
    }

    /// @notice Cut on `amount`, rounded up.
    function cutOf(uint256 amount) public view returns (uint256) {
        uint256 x = amount * cutBps;
        return x == 0 ? 0 : (x - 1) / BPS + 1;
    }

    /// @notice Everything the vault must hold in USDG.
    function reserved() public view returns (uint256) {
        return livePaid + liveBacking + creditPool + pendingCut + totalOwed;
    }

    /// @notice Credit leaf, domain-tagged so roots from QDrops, other chains or other deployments never verify here
    ///         (audit L-3). Off-chain: script/CreditTree.sol builds the same leaf.
    function creditLeaf(address account, uint256 cumulative) public view returns (bytes32) {
        return keccak256(
            bytes.concat(keccak256(abi.encode("QStampCredits", block.chainid, address(this), account, cumulative)))
        );
    }

    /// @notice Sorted-pair Merkle proof check (OpenZeppelin MerkleProof convention, as QDrops).
    function verify(bytes32[] calldata proof, bytes32 root, bytes32 node) public pure returns (bool) {
        if (root == bytes32(0)) return false;
        for (uint256 i; i < proof.length; ++i) {
            bytes32 p = proof[i];
            node = node < p ? keccak256(abi.encodePacked(node, p)) : keccak256(abi.encodePacked(p, node));
        }
        return node == root;
    }

    function domainSeparator() public view returns (bytes32) {
        return block.chainid == _chainId ? _domainSeparator : _buildDomain();
    }

    // ================================================================== internals

    function _buildDomain() internal view returns (bytes32) {
        return keccak256(
            abi.encode(DOMAIN_TYPEHASH, keccak256("QStampVault"), keccak256("2"), block.chainid, address(this))
        );
    }

    function _newKey(address sender, address recipient, bytes32 helloId, address payer)
        internal
        view
        returns (bytes32 key)
    {
        if (recipient == address(0) || recipient == sender || recipient == address(this)) revert BadAddress();
        if (helloId == bytes32(0)) revert BadParams();
        key = stampKey(sender, helloId, payer);
        if (_stamps[key].status != Status.None) revert HelloIdUsed();
    }

    function _validSig(address wallet, bytes32 digest, bytes calldata sig) internal view returns (bool) {
        if (wallet.code.length != 0) {
            bytes memory data = abi.encodeWithSelector(ERC1271_MAGIC, digest, sig);
            bool ok;
            bytes32 res;
            assembly ("memory-safe") {
                mstore(0x00, 0)
                ok := staticcall(gas(), wallet, add(data, 0x20), mload(data), 0x00, 0x20) // copies <= 32 bytes
                res := mload(0x00)
                ok := and(ok, gt(returndatasize(), 31))
            }
            return ok && res == bytes32(ERC1271_MAGIC);
        }
        if (sig.length != 65) return false;
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > HALF_N || (v != 27 && v != 28)) return false;
        address rec = ecrecover(digest, v, r, s);
        return rec != address(0) && rec == wallet;
    }

    function _tryPermit(address owner_, uint256 deadline, uint8 v, bytes32 r, bytes32 s) internal {
        // Skip when the allowance already covers the stamp, so a larger standing approval is never cut down to
        // stampPrice (audit I-2). permit failure is ignored (front-run / already used); the pull checks allowance.
        (bool okA, bytes memory ret) =
            usdg.staticcall(abi.encodeWithSelector(0xdd62ed3e, owner_, address(this)));
        if (okA && ret.length >= 32 && abi.decode(ret, (uint256)) >= stampPrice) return;
        (bool ok,) = usdg.call(
            abi.encodeWithSelector(0xd505accf, owner_, address(this), stampPrice, deadline, v, r, s)
        );
        ok; // allowance is checked by the pull
    }

    /// @dev Redirect guard for acceptTo / withdrawTo (fails closed via isFrozen).
    function _notFrozen(address account) internal view {
        if (isFrozen(account)) revert Frozen(account);
    }

    /// @dev Push; on failure credit `owed` instead of reverting (accepts / refunds can never be blocked).
    function _pay(address to, uint256 amount) internal {
        if (amount == 0) return;
        if (!_tryTransfer(usdg, to, amount)) {
            owed[to] += amount;
            totalOwed += amount;
            emit PayoutDeferred(to, amount);
        }
    }

    /// @dev ERC-20 transfer that never reverts: false on revert, false return, or no code. Copies <= 32 bytes.
    function _tryTransfer(address token, address to, uint256 amount) internal returns (bool ok) {
        bytes memory data = abi.encodeWithSelector(0xa9059cbb, to, amount);
        assembly ("memory-safe") {
            mstore(0x00, 0)
            ok := call(gas(), token, 0, add(data, 0x20), mload(data), 0x00, 0x20)
            switch returndatasize()
            case 0 { ok := and(ok, gt(extcodesize(token), 0)) }
            default { ok := and(ok, and(gt(returndatasize(), 31), eq(mload(0x00), 1))) }
        }
    }

    /// @dev transferFrom into this contract; the balance must rise by exactly `amount` (rejects fee-on-transfer).
    function _pullExact(address from, uint256 amount) internal {
        address token = usdg;
        uint256 beforeBal = _balanceOf(token, address(this));
        bytes memory data = abi.encodeWithSelector(0x23b872dd, from, address(this), amount);
        bool ok;
        assembly ("memory-safe") {
            mstore(0x00, 0)
            ok := call(gas(), token, 0, add(data, 0x20), mload(data), 0x00, 0x20)
            switch returndatasize()
            case 0 { ok := and(ok, gt(extcodesize(token), 0)) }
            default { ok := and(ok, and(gt(returndatasize(), 31), eq(mload(0x00), 1))) }
        }
        if (!ok) revert TransferFailed();
        uint256 afterBal = _balanceOf(token, address(this));
        uint256 got = afterBal > beforeBal ? afterBal - beforeBal : 0;
        if (got != amount) revert AmountMismatch(amount, got);
    }

    function _balanceOf(address token, address who) internal view returns (uint256 bal) {
        (bool ok, bytes memory ret) = token.staticcall(abi.encodeWithSelector(0x70a08231, who));
        if (!ok || ret.length < 32) revert TransferFailed();
        bal = abi.decode(ret, (uint256));
    }
}
